{Spin2_v45}
CON
  STRUCT point(x, y)           ' x and y are LONGs (8 bytes total)

' Compare two long arrays
if LONGCOMP(@results1, @results2, 256)
  ' Arrays match (256 longs)

' Verify calculation results
if LONGCOMP(@computed, @expected, 32)
  ' All 32 computed values match expected

' Check for signature pattern
if LONGCOMP(@header, @valid_signature, 4)
  ' Found valid 4-long signature

' Compare two strings
if STRCOMP(@input, STRING("hello"))
  ' Strings match

' Compare two strings
if BYTECOMP(@string1, @string2, 10)
  ' First 10 bytes match

' Verify buffer contents
if BYTECOMP(@buffer, @expected, 256)
  ' Buffer matches expected data

' Check for pattern
if BYTECOMP(@data[offset], @pattern, 4)
  ' Found 4-byte pattern at offset

' Use in comparison
if STRCOMP(@input, STRING("YES"))
  proceed()

' Compare two word arrays
if WORDCOMP(@array1, @array2, 100)
  ' Arrays match (100 words)

' Verify sensor data
if WORDCOMP(@readings, @expected, 64)
  ' All 64 sensor readings match expected

' Check for word pattern
if WORDCOMP(@data[i], @signature, 4)
  ' Found 4-word signature at position i
